class Solution {
public:
    string smallestFromLeaf(TreeNode* root) {
        string smallest = "~";
        string path = "";
        auto dfs = [&](auto& self, TreeNode* node) -> void {
            if (!node) return;
            path.push_back((char)('a' + node->val));
            if (!node->left && !node->right) {
                string rev = path;
                reverse(rev.begin(), rev.end());
                if (rev < smallest) smallest = rev;
            } else {
                self(self, node->left);
                self(self, node->right);
            }
            path.pop_back();
        };
        dfs(dfs, root);
        return smallest;
    }
};

class Solution {
    private String smallest = "~";
    private StringBuilder path = new StringBuilder();
    private void dfs(TreeNode node) {
        if (node == null) return;
        path.append((char) ('a' + node.val));
        if (node.left == null && node.right == null) {
            String rev = new StringBuilder(path).reverse().toString();
            if (rev.compareTo(smallest) < 0) smallest = rev;
        } else {
            dfs(node.left);
            dfs(node.right);
        }
        path.deleteCharAt(path.length() - 1);
    }
    public String smallestFromLeaf(TreeNode root) {
        smallest = "~";
        path.setLength(0);
        dfs(root);
        return smallest;
    }
}

var smallestFromLeaf = function(root) {
    let smallest = '~';
    const path = [];
    const dfs = (node) => {
        if (!node) return;
        path.push(String.fromCharCode(97 + node.val));
        if (!node.left && !node.right) {
            const rev = path.slice().reverse().join('');
            if (rev < smallest) smallest = rev;
        } else {
            dfs(node.left);
            dfs(node.right);
        }
        path.pop();
    };
    dfs(root);
    return smallest;
};
